<?php
require_once __DIR__.'/../_shared/admin-auth.php';
bp_cors('GET, OPTIONS');$studentId=(int)($_GET['student_id']??$_GET['studentId']??0);
if($studentId<=0){echo json_encode(['status'=>'error','message'=>'Invalid student_id.','quizzes'=>[]]);exit;}
$c=bp_admin_conn();$s=$c->prepare('SELECT q.quiz_id,q.material_id,q.quiz_type,q.difficulty,q.date_created,lm.title material_title,CONCAT("Quiz #",q.quiz_id) quiz_title,COUNT(qq.question_id) question_count FROM quiz q INNER JOIN learning_material lm ON lm.material_id=q.material_id INNER JOIN study_schedule ss ON ss.schedule_id=lm.schedule_id AND ss.student_id=? AND ss.date_deleted IS NULL LEFT JOIN quiz_questions qq ON qq.quiz_id=q.quiz_id WHERE lm.date_deleted IS NULL AND lm.approval_status="approved" AND q.approval_status="approved" GROUP BY q.quiz_id,q.material_id,q.quiz_type,q.difficulty,q.date_created,lm.title ORDER BY q.date_created DESC');$s->bind_param('i',$studentId);$s->execute();$r=$s->get_result();$out=[];while($row=$r->fetch_assoc()){$row['quiz_id']=(int)$row['quiz_id'];$row['material_id']=(int)$row['material_id'];$row['question_count']=(int)$row['question_count'];$out[]=$row;}$s->close();$c->close();echo json_encode(['status'=>'success','quizzes'=>$out]);
